import{_ as t}from"./chunks/ark_sam_gps.CC9RVy77.js";import{_ as e,c as r,al as o,o as i}from"./chunks/framework.DCERqlYr.js";const S=JSON.parse('{"title":"ARK SAM GPS","description":"","frontmatter":{},"headers":[],"relativePath":"ko/gps_compass/ark_sam_gps.md","filePath":"ko/gps_compass/ark_sam_gps.md"}'),n={name:"ko/gps_compass/ark_sam_gps.md"};function l(s,a,d,h,c,p){return i(),r("div",null,a[0]||(a[0]=[o('<h1 id="ark-sam-gps" tabindex="-1">ARK SAM GPS <a class="header-anchor" href="#ark-sam-gps" aria-label="Permalink to &quot;ARK SAM GPS&quot;">​</a></h1><p><a href="https://arkelectron.gitbook.io/ark-documentation/gps/ark-sam-gps%3E" target="_blank" rel="noreferrer">ARK SAM GPS</a> is a made in the USA and NDAA-compliant <a href="./../gps_compass/">GNSS/GPS</a> u-blox SAM-M10Q GPS and industrial magnetometer.</p><p><img src="'+t+'" alt="ARK SAM GPS"></p><h2 id="구매처" tabindex="-1">구매처 <a class="header-anchor" href="#구매처" aria-label="Permalink to &quot;구매처&quot;">​</a></h2><p>Order this module from:</p><ul><li><a href="https://arkelectron.com/product/ark-sam-gps/" target="_blank" rel="noreferrer">ARK Electronics</a> (US)</li></ul><h2 id="hardware-specifications" tabindex="-1">Hardware Specifications <a class="header-anchor" href="#hardware-specifications" aria-label="Permalink to &quot;Hardware Specifications&quot;">​</a></h2><ul><li><a href="https://github.com/ARK-Electronics/ARK_SAM_GPS/tree/main" target="_blank" rel="noreferrer">Open Source Schematic and BOM</a></li><li>센서 <ul><li><a href="https://www.u-blox.com/en/product/sam-m10q-module" target="_blank" rel="noreferrer">u-blox SAM-M10Q</a><ul><li>Less than 38 mW power consumption without compromising GNSS performance</li><li>Maximum position availability with 4 concurrent GNSS reception</li><li>Advanced spoofing and jamming detection</li></ul></li><li><a href="https://www.st.com/en/mems-and-sensors/iis2mdc.html" target="_blank" rel="noreferrer">ST IIS2MDC Magnetometer</a></li></ul></li><li>Pixhawk Standard UART/I2C Connector (6 Pin JST SH)</li><li>Power Requirements <ul><li>5V</li><li>15mA Average</li><li>20mA Max</li></ul></li><li>LED Indicators <ul><li>GPS Fix</li></ul></li><li>USA Built</li><li>NDAA Compliant</li><li>6 Pin Pixhawk Standard UART/I2C Cable</li></ul><h2 id="하드웨어-설정" tabindex="-1">하드웨어 설정 <a class="header-anchor" href="#하드웨어-설정" aria-label="Permalink to &quot;하드웨어 설정&quot;">​</a></h2><p>The module comes with a Pixhawk-standard 6pin connector that will plug into the <code>GPS2</code> port on recent Pixhawk flight controllers. It should be mounted front facing, as far away from the flight controller and other electronics as possible.</p><p>For more information see <a href="./../gps_compass/#mounting-the-gnss-compass">Mounting the GNSS/Compass</a> and <a href="./../gps_compass/#hardware-setup">Hardware Setup</a>.</p><h2 id="px4-설정" tabindex="-1">PX4 설정 <a class="header-anchor" href="#px4-설정" aria-label="Permalink to &quot;PX4 설정&quot;">​</a></h2><p>The module should be plug-n-play when used with the <code>GPS2</code> port on most flight controllers.</p><p><a href="./../gps_compass/#secondary-gps-configuration-uart">Secondary GPS Configuration (UART)</a> explains how you can configure the port if the GPS is not detected (note, that the configuration is the same, even if you are using GPS 2 as the primary compass).</p><h2 id="핀배열" tabindex="-1">핀배열 <a class="header-anchor" href="#핀배열" aria-label="Permalink to &quot;핀배열&quot;">​</a></h2><h3 id="pixhawk-standard-uart-i2c-connector-6-pin-jst-sh" tabindex="-1">Pixhawk Standard UART/I2C Connector - 6 Pin JST-SH <a class="header-anchor" href="#pixhawk-standard-uart-i2c-connector-6-pin-jst-sh" aria-label="Permalink to &quot;Pixhawk Standard UART/I2C Connector - 6 Pin JST-SH&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin Number</th><th>Signal Name</th><th>전압</th></tr></thead><tbody><tr><td>1</td><td>5V</td><td>5.0V</td></tr><tr><td>2</td><td>RX</td><td>3.3V</td></tr><tr><td>3</td><td>TX</td><td>3.3V</td></tr><tr><td>4</td><td>SCL</td><td>3.3V</td></tr><tr><td>5</td><td>SDA</td><td>3.3V</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="https://arkelectron.gitbook.io/ark-documentation/gps/ark-sam-gps" target="_blank" rel="noreferrer">ARK SAM GPS Documentation</a> (ARK Docs)</li></ul>',19)]))}const f=e(n,[["render",l]]);export{S as __pageData,f as default};
